/* · THE WATCHERS · — app.js
 *
 * Public site: the watchers rendered as a cyberpunk node graph, with a reader
 * for each watcher's latest edition. Watcher metadata mirrors the packages/ tree
 * and docs/digest-package-portfolio-design.md as of 2026-10-13; edition content
 * comes from data/editions.js, generated by scripts/export-web-editions.js.
 */
(() => {
  "use strict";

  const t = (es, en) => ({ es, en });
  const pad = (n) => String(n).padStart(2, "0");
  const lang = () => document.documentElement.dataset.lang;
  const tr = (v) => (v && typeof v === "object" ? v[lang()] : v);
  const EDITIONS = window.WATCHERS_EDITIONS || {};

  // ---------- data ----------

  const STATUS = {
    core: t("Red", "Network"),
    live: t("En línea", "Online"),
    planned: t("Próximamente", "Coming soon"),
    source: t("Fuente", "Source"),
    edition: t("Edición", "Edition"),
  };

  const FIELDS = [
    ["method", t("Método", "Method")],
    ["question", t("Misión", "Mission")],
    ["horizon", t("Horizonte", "Horizon")],
    ["output", t("Entrega", "Delivers")],
    ["sources", t("Fuentes", "Sources")],
    ["language", t("Idioma", "Language")],
  ];

  const COPY = {
    noEdition: t("Este watcher aún no ha publicado ninguna edición.", "This watcher has not published an edition yet."),
    about: t("Sobre este watcher", "About this watcher"),
    minutes: t("min de lectura", "min read"),
    summary: t("Resumen", "Summary"),
    back: t("Volver al resumen", "Back to summary"),
  };

  const NODES = [
    {
      id: "the-watchers", kind: "core", status: "core", label: "THE WATCHERS",
      title: t("The Watchers", "The Watchers"),
      summary: t(
        "Vigilantes automáticos de fuentes públicas. Cada watcher sigue un conjunto fijo de cuentas, podcasts y blogs, y publica ediciones con enlaces a cada fuente. Elige un watcher en línea para leer su última edición.",
        "Automated watchers over public sources. Each watcher follows a fixed set of accounts, podcasts and blogs, and publishes editions that link to every source. Pick an online watcher to read its latest edition."
      ),
      method: t(
        "Un modelo de lenguaje redacta cada edición a partir de las fuentes vigiladas y enlaza cada noticia a su origen.",
        "A language model drafts each edition from the watched sources and links every story to its origin."
      ),
    },
    {
      id: "ai-builders-digest", kind: "digest", status: "live", label: "AI-BUILDERS",
      title: t("AI Builders", "AI Builders"),
      summary: t(
        "Monitoriza a builders de IA en X, podcasts y blogs, y condensa lo que construyen en resúmenes legibles. Builders, no influencers.",
        "Monitors top AI builders on X, podcasts and blogs, and remixes what they ship into digestible summaries. Follow builders, not influencers."
      ),
      sources: "26 X · 6 podcasts · 2 blogs",
      language: "EN",
    },
    {
      id: "cybersecurity-digest", kind: "digest", status: "live", label: "CYBERSECURITY",
      title: t("Ciberseguridad", "Cybersecurity"),
      summary: t(
        "Digest defensivo en español con evidencia enlazada y etiquetas de incertidumbre.",
        "Spanish defensive cybersecurity digest with linked evidence and uncertainty labels."
      ),
      question: t(
        "¿Qué acción defensiva debe tomar un operador o propietario?",
        "What defensive action should an operator or owner take?"
      ),
      horizon: t("Inmediato a corto plazo", "Immediate to near term"),
      output: t(
        "Exposición, activos afectados, mitigaciones, detección, prioridad de remediación.",
        "Exposure, affected assets, mitigations, detection, remediation priority."
      ),
      sources: "40 X",
      language: "ES",
    },
    {
      id: "cyber-intelligence-digest", kind: "digest", status: "planned", label: "CYBER-INTEL",
      title: t("Ciberinteligencia", "Cyber Intelligence"),
      question: t(
        "¿Qué responde la evidencia sobre un requisito prioritario de inteligencia, un adversario, una campaña, una intención o una capacidad?",
        "What does the evidence answer about a priority intelligence requirement, adversary, campaign, intent, or capability?"
      ),
      horizon: t("Cercano a estratégico", "Near to strategic"),
      output: t(
        "Evaluación ligada a PIR, contexto de TTP y campañas, confianza, lagunas, necesidades de obtención.",
        "PIR-linked assessment, TTP/campaign context, confidence, gaps, collection needs."
      ),
    },
    {
      id: "intelligence-geopolitics-digest", kind: "digest", status: "planned", label: "INTEL-GEOPOL",
      title: t("Inteligencia y geopolítica", "Intelligence & Geopolitics"),
      question: t(
        "¿Qué significa este desarrollo para el comportamiento de los Estados, las instituciones, las políticas y los futuros plausibles?",
        "What does this development mean for state behavior, institutions, policy, and plausible futures?"
      ),
      horizon: t("Medio a largo plazo", "Medium to long horizon"),
      output: t(
        "Juicios estratégicos, impulsores, alternativas, indicadores, implicaciones, incertidumbre.",
        "Strategic judgments, drivers, alternatives, indicators, implications, uncertainty."
      ),
    },
    {
      id: "armed-conflicts-geopolitics-digest", kind: "digest", status: "planned", label: "ARMED-CONFLICTS",
      title: t("Conflictos armados", "Armed Conflicts"),
      question: t(
        "¿Qué ocurrió, dónde, cuándo y con qué efectos verificados sobre el conflicto y la situación humanitaria?",
        "What happened, where, when, with what verified conflict and humanitarian effects?"
      ),
      horizon: t("Cronología de eventos y efectos a corto plazo", "Event chronology plus near-term effects"),
      output: t(
        "Cronología con fuentes, actor/acción/lugar, cambios de control o efecto, afirmaciones disputadas.",
        "Sourced timeline, actor/action/location, control/effect changes, disputed claims."
      ),
    },
    {
      id: "spanish-national-politics-digest", kind: "digest", status: "planned", label: "ES-POLITICS",
      title: t("Política española", "Spanish Politics"),
      question: t(
        "¿Qué decisión institucional española se produjo, o qué desarrollo tiene un impacto material en España?",
        "What Spanish institutional decision occurred, or what development has material impact on Spain?"
      ),
      horizon: t("Diario a horizonte de políticas", "Daily to policy horizon"),
      output: t(
        "Recorrido de la decisión, competencia, estatus legal, impacto parlamentario, electoral o de políticas.",
        "Decision path, competence, legal status, parliamentary/electoral/policy impact."
      ),
    },
    {
      id: "x-clusters-digest", kind: "digest", status: "planned", label: "X-CLUSTERS",
      title: t("Clústeres de X", "X Clusters"),
      question: t(
        "¿Qué publican, amplifican, citan o responden los miembros configurados en X, y qué contexto conecta esas observaciones?",
        "What are configured public X members posting, amplifying, quoting, or replying to, and what context connects those observations?"
      ),
      horizon: t("Observación entre sondeos", "Poll-to-poll observation"),
      output: t(
        "Actividad de clústeres y miembros, contexto relacional, cambios, transiciones de disponibilidad.",
        "Cluster/member activity, relationship context, changes, availability transitions."
      ),
    },

    // satellites: sources feed a digest, editions come out of it
    {
      id: "ai-x", kind: "source", parent: "ai-builders-digest", label: "X ×26",
      title: t("Cuentas de X", "X accounts"),
      summary: t("26 cuentas de builders monitorizadas.", "26 builder accounts monitored."),
    },
    {
      id: "ai-pod", kind: "source", parent: "ai-builders-digest", label: "POD ×6",
      title: t("Podcasts", "Podcasts"),
      summary: t("6 podcasts monitorizados.", "6 podcasts monitored."),
    },
    {
      id: "ai-blog", kind: "source", parent: "ai-builders-digest", label: "BLOG ×2",
      title: t("Blogs", "Blogs"),
      summary: t("2 blogs monitorizados.", "2 blogs monitored."),
    },
    {
      id: "cy-x", kind: "source", parent: "cybersecurity-digest", label: "X ×40",
      title: t("Cuentas de X", "X accounts"),
      summary: t("40 cuentas defensivas monitorizadas.", "40 defensive accounts monitored."),
    },
  ];

  const editionDate = (iso, options) =>
    new Intl.DateTimeFormat(lang(), { timeZone: "UTC", ...options }).format(new Date(iso));

  // one edition satellite per watcher that has actually published
  for (const [id, edition] of Object.entries(EDITIONS)) {
    if (!NODES.some((n) => n.id === id && n.status === "live")) continue;
    NODES.push({
      id: `${id}-edition`, kind: "edition", parent: id,
      get label() {
        return `ED ${editionDate(edition.generatedAt, { day: "2-digit", month: "short" }).replace(".", "").toUpperCase()}`;
      },
    });
  }

  // Routing rules 2 and 3 of the portfolio design: neighbours that must not collapse.
  const ROUTES = [
    ["cybersecurity-digest", "cyber-intelligence-digest"],
    ["intelligence-geopolitics-digest", "armed-conflicts-geopolitics-digest"],
  ];

  // ---------- graph model ----------

  const RADIUS = { core: 68, digest: 40.48, source: 11, edition: 11 };
  const byId = new Map(NODES.map((n) => [n.id, n]));
  const core = byId.get("the-watchers");
  const digests = NODES.filter((n) => n.kind === "digest");
  const listed = [core, ...digests];
  const EDGES = [];

  for (const n of NODES) {
    n.r = RADIUS[n.kind];
    n.rr = n.r;
    n.x = n.y = n.vx = n.vy = 0;
    n.phase = Math.random() * Math.PI * 2;
    n.u = n.v = 0;
    if (n.parent) {
      const p = byId.get(n.parent);
      n.status = p.status;
      EDGES.push(n.kind === "source" ? { a: n, b: p, kind: "feed" } : { a: p, b: n, kind: "out" });
    }
    if (n.kind === "digest") EDGES.push({ a: n, b: core, kind: "bus" });
  }
  for (const [a, b] of ROUTES) EDGES.push({ a: byId.get(a), b: byId.get(b), kind: "route" });

  // digests sit on an ellipse around the core; (u, v) are unit-ellipse coordinates.
  // Live digests take the wide left/right slots so their satellites have room;
  // routing neighbours sit next to each other. Degrees, clockwise from the right.
  const RING = {
    "cybersecurity-digest": -15,
    "cyber-intelligence-digest": 35,
    "armed-conflicts-geopolitics-digest": 90,
    "intelligence-geopolitics-digest": 140,
    "ai-builders-digest": 192,
    "x-clusters-digest": 245,
    "spanish-national-politics-digest": 295,
  };
  Object.entries(RING).forEach(([id, degrees], index) => {
    const n = byId.get(id);
    n.sides = [6, 4, 8][index % 3];
    const a = (degrees * Math.PI) / 180;
    n.u = Math.cos(a);
    n.v = Math.sin(a);
  });

  // satellites fan outward from their parent; (ox, oy) is an unscaled offset
  const children = new Map();
  for (const n of NODES) {
    if (!n.parent) continue;
    if (!children.has(n.parent)) children.set(n.parent, []);
    children.get(n.parent).push(n);
  }
  for (const [pid, kids] of children) {
    const p = byId.get(pid);
    const base = Math.atan2(p.v, p.u);
    kids.forEach((k, i) => {
      const a = base + (i - (kids.length - 1) / 2) * 0.62;
      k.ox = Math.cos(a) * 68;
      k.oy = Math.sin(a) * 68;
    });
  }

  const isLive = (e) => e.a.status !== "planned" && e.b.status !== "planned";
  const touches = (e, n) => n && (e.a === n || e.b === n);

  // ---------- dom ----------

  const root = document.documentElement;
  const canvas = document.getElementById("graph");
  const ctx = canvas.getContext("2d");
  const list = document.getElementById("nodeList");
  const details = document.getElementById("details");
  const panel = document.getElementById("panel");
  const detailsIndex = document.getElementById("detailsIndex");
  const detailsStatus = document.getElementById("detailsStatus");
  const detailsTitle = document.getElementById("detailsTitle");
  const detailsSummary = document.getElementById("detailsSummary");
  const detailsRows = document.getElementById("detailsRows");
  const detailsEdition = document.getElementById("detailsEdition");
  const langToggle = document.getElementById("langToggle");
  const themeToggle = document.getElementById("themeToggle");
  const sysClock = document.getElementById("sysClock");
  const sysLast = document.getElementById("sysLast");

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const liveCount = digests.filter((n) => n.status === "live").length;
  const latestEdition = Object.values(EDITIONS)
    .map((e) => e.generatedAt)
    .sort()
    .at(-1);

  document.getElementById("digestCount").textContent = pad(digests.length);
  document.getElementById("liveCount").textContent = pad(liveCount);
  document.getElementById("plannedCount").textContent = pad(digests.filter((n) => n.status === "planned").length);

  // ---------- preferences (per-viewer convenience only) ----------

  const PREFS_KEY = "digest-net:prefs";
  const prefs = (() => {
    try { return JSON.parse(localStorage.getItem(PREFS_KEY)) || {}; } catch { return {}; }
  })();
  const savePrefs = () => {
    try { localStorage.setItem(PREFS_KEY, JSON.stringify(prefs)); } catch { /* storage unavailable */ }
  };

  // ---------- state ----------

  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
  let motion = !reduceMotion.matches;
  reduceMotion.addEventListener("change", (e) => { motion = !e.matches; });

  let W = 0, H = 0, DPR = 1;
  let P = {};
  let region = { x0: 0, y0: 0, x1: 0, y1: 0 };
  let geo = { cx: 0, cy: 0, rx: 0, ry: 0, s: 1 };
  let hovered = null;
  let selected = null;
  let openStory = null; // item block shown instead of the edition summary
  let drag = null;
  const packets = [];

  // ---------- palette ----------

  function hexAlpha(hex, a) {
    const n = parseInt(hex.slice(1), 16);
    return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a})`;
  }

  function readPalette() {
    const cs = getComputedStyle(root);
    const v = (k) => cs.getPropertyValue(k).trim();
    P = {
      bg: v("--bg"), ink: v("--ink"), term: v("--term"), muted: v("--muted"),
      live: v("--neon-live"), core: v("--neon-core"), out: v("--neon-out"), off: v("--neon-off"),
      grid: v("--grid"),
      hue: Object.fromEntries(digests.map((n) => [n.id, v(`--hue-${n.id}`) || v("--neon-live")])),
      glow: root.dataset.theme === "light" ? 0.35 : 1,
    };
  }

  // ---------- layout ----------

  function measure() {
    const cs = getComputedStyle(root);
    const barT = parseFloat(cs.getPropertyValue("--bar-t")) || 0;
    const barB = parseFloat(cs.getPropertyValue("--bar-b")) || 0;
    const phone = W <= 760;
    let x0 = 0, x1 = W, y0 = barT, y1 = H - barB;
    const pr = panel.getBoundingClientRect();
    if (phone) {
      y1 = Math.max(y0 + 220, pr.top);
    } else if (pr.left - x0 > 360) {
      // a wide panel on a narrow desktop overlays the graph instead of crushing it
      x1 = pr.left;
    }
    region = { x0: x0 + 16, y0: y0 + 16, x1: x1 - 16, y1: y1 - 16 };
    const w = region.x1 - region.x0;
    const h = region.y1 - region.y0;
    const s = clamp(Math.min(w, h) / 620, 0.5, 1.15);
    // portrait screens turn the ring a quarter so live digests move to top and bottom
    const portrait = h > w * 1.1;
    geo = {
      cx: region.x0 + w / 2,
      cy: region.y0 + h / 2,
      rx: Math.max(40, w / 2 - (portrait ? 90 : 160) * s),
      ry: Math.max(40, h / 2 - (portrait ? 110 : 84) * s),
      s,
      portrait,
    };
  }

  // ring space -> screen space
  const toScreen = (u, v) => (geo.portrait ? [v, -u] : [u, v]);

  function home(n) {
    if (n.parent) {
      const p = byId.get(n.parent);
      return [p.x + n.ox * geo.s, p.y + n.oy * geo.s];
    }
    const [u, v] = toScreen(n.u, n.v);
    return [geo.cx + u * geo.rx, geo.cy + v * geo.ry];
  }

  function resize() {
    DPR = Math.min(2, window.devicePixelRatio || 1);
    W = window.innerWidth;
    H = window.innerHeight;
    canvas.width = Math.round(W * DPR);
    canvas.height = Math.round(H * DPR);
    measure();
  }

  function seed() {
    for (const n of NODES) if (!n.parent) [n.x, n.y] = home(n);
    for (const n of NODES) if (n.parent) [n.x, n.y] = home(n);
  }

  // ---------- simulation ----------

  function step(time, dt) {
    const s = geo.s;
    const k = clamp(dt / 16.7, 0, 3);

    for (const n of NODES) {
      n.rr = n.r * s;
      if (drag && drag.node === n) continue;
      let [hx, hy] = home(n);
      if (motion) {
        hx += Math.cos(time / 1700 + n.phase) * 3 * s;
        hy += Math.sin(time / 2100 + n.phase) * 3 * s;
      }
      n.vx += (hx - n.x) * 0.03 * k;
      n.vy += (hy - n.y) * 0.03 * k;
    }

    // soft collision keeps labels from stacking
    for (let i = 0; i < NODES.length; i++) {
      for (let j = i + 1; j < NODES.length; j++) {
        const a = NODES[i], b = NODES[j];
        const dx = b.x - a.x, dy = b.y - a.y;
        const d = Math.hypot(dx, dy) || 0.01;
        const min = a.rr + b.rr + 26 * s;
        if (d >= min) continue;
        const f = ((min - d) * 0.08 * k) / d;
        a.vx -= dx * f; a.vy -= dy * f;
        b.vx += dx * f; b.vy += dy * f;
      }
    }

    for (const n of NODES) {
      if (drag && drag.node === n) { n.vx = n.vy = 0; continue; }
      n.vx *= 0.8; n.vy *= 0.8;
      n.x = clamp(n.x + n.vx, region.x0 + n.rr, region.x1 - n.rr);
      n.y = clamp(n.y + n.vy, region.y0 + n.rr, region.y1 - n.rr);
    }

    if (motion) {
      for (const e of EDGES) {
        if (e.kind === "route" || !isLive(e) || time < (e.next || 0)) continue;
        packets.push({ e, t: 0, v: 0.006 + Math.random() * 0.006 });
        e.next = time + 900 + Math.random() * 2600;
      }
    }
    for (let i = packets.length - 1; i >= 0; i--) {
      packets[i].t += packets[i].v * k;
      if (packets[i].t >= 1 || !motion) packets.splice(i, 1);
    }
  }

  // ---------- drawing ----------

  // The middle of the core's octagon face that looks toward n, and the bend on the way
  // there: the trace leaves the face square to it, then turns once to reach n.
  function corePort(n) {
    const k = Math.round(Math.atan2(n.y - core.y, n.x - core.x) / (Math.PI / 4));
    const nx = Math.round(Math.cos((k * Math.PI) / 4));
    const ny = Math.round(Math.sin((k * Math.PI) / 4));
    const f = core.rr / Math.hypot(nx, ny);
    const fx = core.x + nx * f, fy = core.y + ny * f;
    const dx = n.x - fx, dy = n.y - fy;
    let t;
    if (nx && ny) {
      // diagonal face: then a straight run to n
      t = Math.min(dx * nx, dy * ny);
    } else {
      // side face: then a 45° run to n, or a square turn when n is too close for one
      const along = dx * nx + dy * ny, across = Math.abs(nx ? dy : dx);
      t = along >= across ? along - across : along;
    }
    t = Math.max(0, t);
    return [[fx, fy], [fx + nx * t, fy + ny * t]];
  }

  // circuit-board trace: one 45° run, then a straight run into the target
  function route(e) {
    const { a, b } = e;
    if (a === core || b === core) {
      const [face, bend] = corePort(a === core ? b : a);
      return a === core ? [face, bend, [b.x, b.y]] : [[a.x, a.y], bend, face];
    }
    const dx = b.x - a.x, dy = b.y - a.y;
    const bend = Math.abs(dx) > Math.abs(dy)
      ? [a.x + Math.sign(dx) * Math.abs(dy), b.y]
      : [b.x, a.y + Math.sign(dy) * Math.abs(dx)];
    return [[a.x, a.y], bend, [b.x, b.y]];
  }

  function tracePath(e) {
    const [p0, p1, p2] = route(e);
    ctx.beginPath();
    ctx.moveTo(...p0);
    ctx.lineTo(...p1);
    ctx.lineTo(...p2);
  }

  function pointAt(e, t) {
    const [[ax, ay], [mx, my], [bx, by]] = route(e);
    const l1 = Math.hypot(mx - ax, my - ay);
    const l2 = Math.hypot(bx - mx, by - my);
    const d = t * (l1 + l2);
    if (d <= l1 || l2 === 0) {
      const q = l1 ? d / l1 : 0;
      return [ax + (mx - ax) * q, ay + (my - ay) * q];
    }
    const q = (d - l1) / l2;
    return [mx + (bx - mx) * q, my + (by - my) * q];
  }

  // each digest has its own colour, and its sources share it
  const hue = (n) => (n.kind === "core" ? P.core : P.hue[n.parent || n.id]);
  // the colour a node is drawn in: editions keep the output colour
  const tint = (n) => (n.kind === "edition" ? P.out : hue(n));

  function edgeColors(e) {
    return [hue(e.a), e.kind === "out" ? P.out : hue(e.b)];
  }

  function drawFloor(time) {
    const horizon = region.y0 + (region.y1 - region.y0) * 0.56;
    const depth = H - horizon;
    const vx = geo.cx;
    ctx.save();
    ctx.strokeStyle = P.grid;
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let i = -18; i <= 18; i++) {
      ctx.moveTo(vx + i * 10, horizon);
      ctx.lineTo(vx + i * (W / 9), H);
    }
    const off = motion ? (time / 2600) % 1 : 0;
    for (let i = 0; i < 14; i++) {
      const z = (i + off) / 14;
      const y = horizon + depth * z * z;
      ctx.moveTo(0, y);
      ctx.lineTo(W, y);
    }
    ctx.stroke();
    const fade = ctx.createLinearGradient(0, horizon, 0, horizon + depth * 0.5);
    fade.addColorStop(0, P.bg);
    fade.addColorStop(1, hexAlpha(P.bg, 0));
    ctx.fillStyle = fade;
    ctx.fillRect(0, horizon - 1, W, depth * 0.5 + 1);
    ctx.restore();
  }

  function drawHalo() {
    const r = 260 * geo.s;
    const g = ctx.createRadialGradient(core.x, core.y, 0, core.x, core.y, r);
    g.addColorStop(0, hexAlpha(P.core, 0.12 * P.glow));
    g.addColorStop(1, hexAlpha(P.core, 0));
    ctx.fillStyle = g;
    ctx.fillRect(core.x - r, core.y - r, r * 2, r * 2);
  }

  function drawEdge(e) {
    const hot = touches(e, hovered) || touches(e, selected);
    ctx.save();
    if (e.kind === "route" || !isLive(e)) {
      ctx.setLineDash(e.kind === "route" ? [2, 6] : [4, 6]);
      ctx.strokeStyle = hexAlpha(P.off, hot ? 0.95 : 0.55);
      ctx.lineWidth = 1;
      tracePath(e);
      ctx.stroke();
      ctx.restore();
      return;
    }
    const [ca, cb] = edgeColors(e);
    const grad = (a) => {
      const g = ctx.createLinearGradient(e.a.x, e.a.y, e.b.x, e.b.y);
      g.addColorStop(0, hexAlpha(ca, a));
      g.addColorStop(1, hexAlpha(cb, a));
      return g;
    };
    ctx.strokeStyle = grad((hot ? 0.28 : 0.09) * P.glow);
    ctx.lineWidth = 5;
    tracePath(e);
    ctx.stroke();
    ctx.strokeStyle = grad(hot ? 0.95 : 0.5);
    ctx.lineWidth = 1.2;
    tracePath(e);
    ctx.stroke();
    ctx.restore();
  }

  function drawPacket(p) {
    const [x, y] = pointAt(p.e, p.t);
    const [ca, cb] = edgeColors(p.e);
    const c = p.t < 0.5 ? ca : cb;
    ctx.save();
    ctx.shadowColor = c;
    ctx.shadowBlur = 8 * P.glow;
    ctx.fillStyle = c;
    ctx.fillRect(Math.round(x) - 1.5, Math.round(y) - 1.5, 3, 3);
    ctx.restore();
  }

  function polygonPath(x, y, r, sides = 6) {
    ctx.beginPath();
    for (let i = 0; i < sides; i++) {
      const a = Math.PI / sides + (i * Math.PI * 2) / sides;
      const px = x + Math.cos(a) * r, py = y + Math.sin(a) * r;
      if (i) ctx.lineTo(px, py); else ctx.moveTo(px, py);
    }
    ctx.closePath();
  }

  function squarePath(x, y, h, c) {
    ctx.beginPath();
    ctx.moveTo(x - h + c, y - h);
    ctx.arcTo(x + h, y - h, x + h, y + h, c);
    ctx.arcTo(x + h, y + h, x - h, y + h, c);
    ctx.arcTo(x - h, y + h, x - h, y - h, c);
    ctx.arcTo(x - h, y - h, x + h, y - h, c);
    ctx.closePath();
  }

  // regular octagon with flat sides facing the axes, at distance a from the center
  function octagonPath(x, y, a) {
    const R = a / Math.cos(Math.PI / 8);
    ctx.beginPath();
    for (let i = 0; i < 8; i++) {
      const t = Math.PI / 8 + (i * Math.PI) / 4;
      const px = x + Math.cos(t) * R, py = y + Math.sin(t) * R;
      if (i) ctx.lineTo(px, py); else ctx.moveTo(px, py);
    }
    ctx.closePath();
  }

  // The core is a chip whose circuit traces fan out like a brain, with an eye on the die.
  // One quarter of the traces, in units of the node radius (screen axes, so up is -y);
  // the other quarters mirror it. Each trace leaves a pin, bends 45° and ends on a pad.
  const CORE_CHIP = 0.42;
  const CORE_TRACES = [
    [[0.05, -0.28], [0.05, -0.56], [0.10, -0.61], [0.10, -0.72]],
    [[0.14, -0.28], [0.14, -0.46], [0.30, -0.62], [0.30, -0.84]],
    [[0.23, -0.28], [0.23, -0.36], [0.47, -0.60], [0.47, -0.74]],
    [[0.28, -0.05], [0.56, -0.05], [0.61, -0.10], [0.80, -0.10]],
    [[0.28, -0.14], [0.46, -0.14], [0.62, -0.30], [0.84, -0.30]],
    [[0.28, -0.23], [0.36, -0.23], [0.58, -0.45], [0.72, -0.45]],
  ];
  const QUARTERS = [[1, 1], [-1, 1], [1, -1], [-1, -1]];

  // A plain eye: it blinks now and then, looks toward the node in focus and takes its colour.
  function drawEye(n, time) {
    const { x, y } = n;
    const r = n.rr * 1.5;
    const t = (time + n.phase * 1000) % 5200;
    const open = motion && t < 240 ? Math.max(0.08, Math.abs(Math.cos((Math.PI * t) / 240))) : 1;
    const w = r * 0.19, h = r * 0.1 * open;
    const focus = [hovered, selected].find((f) => f && f !== n);
    let gx = 0, gy = 0;
    if (focus) {
      const d = Math.hypot(focus.x - x, focus.y - y) || 1;
      gx = ((focus.x - x) / d) * r * 0.07;
      gy = ((focus.y - y) / d) * r * 0.035;
    }
    const c = focus ? tint(focus) : P.core;
    ctx.beginPath();
    ctx.moveTo(x - w, y);
    ctx.quadraticCurveTo(x, y - h * 2, x + w, y);
    ctx.quadraticCurveTo(x, y + h * 2, x - w, y);
    ctx.closePath();
    ctx.strokeStyle = c;
    ctx.stroke();
    ctx.save();
    ctx.clip();
    ctx.beginPath();
    ctx.arc(x + gx, y + gy, r * 0.085, 0, Math.PI * 2);
    ctx.fillStyle = hexAlpha(c, 0.25);
    ctx.fill();
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(x + gx, y + gy, r * 0.038, 0, Math.PI * 2);
    ctx.fillStyle = c;
    ctx.fill();
    ctx.restore();
  }

  function drawNode(n, time) {
    const { x, y, rr: r } = n;
    const s = geo.s;
    ctx.save();
    ctx.lineWidth = 1.5;

    if (n.kind === "core") {
      // the board: it also hides the ends of the bus traces; every pad fits inside it
      octagonPath(x, y, r);
      ctx.fillStyle = P.bg;
      ctx.fill();
      ctx.strokeStyle = hexAlpha(P.core, 0.55);
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.shadowColor = P.core;
      ctx.shadowBlur = 10 * P.glow;
      ctx.strokeStyle = P.core;
      ctx.lineWidth = 1.5;
      const at = ([px, py], [sx, sy]) => [x + sx * px * r, y + sy * py * r];
      ctx.beginPath();
      for (const q of QUARTERS) {
        for (const trace of CORE_TRACES) {
          trace.forEach((p, i) => ctx[i ? "lineTo" : "moveTo"](...at(p, q)));
        }
      }
      ctx.stroke();
      const pad = Math.max(1.6, r * 0.035);
      ctx.beginPath();
      for (const q of QUARTERS) {
        for (const trace of CORE_TRACES) {
          const [px, py] = at(trace[trace.length - 1], q);
          ctx.moveTo(px + pad, py);
          ctx.arc(px, py, pad, 0, Math.PI * 2);
        }
      }
      ctx.fillStyle = P.bg;
      ctx.fill();
      ctx.stroke();
      squarePath(x, y, r * CORE_CHIP, r * 0.075);
      ctx.fill();
      ctx.stroke();
      ctx.shadowBlur = 0;
      drawEye(n, time);
    } else if (n.kind === "digest" && n.status === "live") {
      const c = hue(n);
      if (motion) {
        const q = (time / 1800 + n.phase) % 1;
        polygonPath(x, y, r + q * 16 * s, n.sides);
        ctx.strokeStyle = hexAlpha(c, (1 - q) * 0.5);
        ctx.stroke();
      }
      ctx.shadowColor = c;
      ctx.shadowBlur = 14 * P.glow;
      polygonPath(x, y, r, n.sides);
      ctx.fillStyle = P.bg;
      ctx.fill();
      ctx.strokeStyle = c;
      ctx.stroke();
      ctx.shadowBlur = 0;
      polygonPath(x, y, r * 0.45);
      ctx.fillStyle = hexAlpha(c, 0.4);
      ctx.fill();
    } else if (n.kind === "digest") {
      const hot = n === hovered || n === selected;
      ctx.setLineDash([3, 4]);
      polygonPath(x, y, r, n.sides);
      ctx.fillStyle = P.bg;
      ctx.fill();
      ctx.strokeStyle = hexAlpha(hue(n), hot ? 1 : 0.6);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.strokeStyle = hexAlpha(hue(n), 0.5);
      ctx.beginPath();
      ctx.moveTo(x - r * 0.28, y);
      ctx.lineTo(x + r * 0.28, y);
      ctx.stroke();
    } else {
      const c = tint(n);
      ctx.shadowColor = c;
      ctx.shadowBlur = 10 * P.glow;
      ctx.beginPath();
      if (n.kind === "source") {
        ctx.moveTo(x, y - r);
        ctx.lineTo(x + r, y);
        ctx.lineTo(x, y + r);
        ctx.lineTo(x - r, y);
        ctx.closePath();
      } else {
        ctx.rect(x - r * 0.8, y - r * 0.8, r * 1.6, r * 1.6);
      }
      ctx.fillStyle = P.bg;
      ctx.fill();
      ctx.strokeStyle = c;
      ctx.stroke();
    }
    ctx.restore();
  }

  function setFont(px, weight = 500) {
    ctx.font = `${weight} ${Math.round(px)}px "JetBrains Mono", monospace`;
    if ("letterSpacing" in ctx) ctx.letterSpacing = `${(px * 0.14).toFixed(1)}px`;
  }

  function plate(text, x, y, px) {
    const w = ctx.measureText(text).width;
    const left = ctx.textAlign === "left" ? x : ctx.textAlign === "right" ? x - w : x - w / 2;
    ctx.fillStyle = hexAlpha(P.bg, 0.78);
    ctx.fillRect(left - 4, y - 2, w + 8, px + 4);
  }

  function drawLabel(n) {
    const s = geo.s;
    const big = n.kind === "core" || n.kind === "digest";
    const px = (n.kind === "core" ? 11 : big ? 10 : 9) * Math.max(0.85, s);
    let x = n.x;
    let y = n.y + n.rr + (n.kind === "core" ? 12 : 8) * s;
    ctx.save();
    ctx.textAlign = "center";
    ctx.textBaseline = "top";

    // satellites label outward, beside the node, so a fan of them stays readable
    if (!big) {
      ctx.textAlign = n.ox < 0 ? "right" : "left";
      x = n.x + Math.sign(n.ox || 1) * (n.rr + 7 * s);
      y = n.y - px / 2;
    }

    setFont(px);
    plate(n.label, x, y, px);
    if (motion && n === hovered && Math.random() < 0.35) {
      ctx.fillStyle = hexAlpha(P.core, 0.8);
      ctx.fillText(n.label, x - 2, y);
      ctx.fillStyle = hexAlpha(P.live, 0.8);
      ctx.fillText(n.label, x + 2, y);
    }
    ctx.fillStyle = n.status === "planned" ? P.muted : big ? P.ink : P.term;
    ctx.fillText(n.label, x, y);

    if (big) {
      const sub = n.kind === "core"
        ? `● ${pad(liveCount)} ${tr(STATUS.live).toUpperCase()}`
        : `${n.status === "planned" ? "○" : "●"} ${tr(STATUS[n.status]).toUpperCase()}`;
      const sy = y + px + 6;
      setFont(px * 0.85);
      plate(sub, x, sy, px * 0.85);
      ctx.fillStyle = n.status === "live" ? hue(n) : n.status === "core" ? P.core : P.muted;
      ctx.fillText(sub, x, sy);
    }
    ctx.restore();
  }

  function drawReticle(n, time, a) {
    const s = geo.s;
    const r = n.rr + 10 * s + (motion ? Math.sin(time / 300) * 1.5 : 0);
    const k = 7 * s;
    ctx.save();
    ctx.strokeStyle = hexAlpha(P.ink, a);
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    for (const sx of [-1, 1]) {
      for (const sy of [-1, 1]) {
        ctx.moveTo(n.x + sx * r, n.y + sy * (r - k));
        ctx.lineTo(n.x + sx * r, n.y + sy * r);
        ctx.lineTo(n.x + sx * (r - k), n.y + sy * r);
      }
    }
    ctx.stroke();
    if (a === 1) {
      setFont(8 * Math.max(0.85, s));
      ctx.fillStyle = hexAlpha(P.ink, 0.7);
      ctx.textAlign = "left";
      ctx.textBaseline = "bottom";
      ctx.fillText(`[${Math.round(n.x)},${Math.round(n.y)}]`, n.x + r + 4, n.y - r);
    }
    ctx.restore();
  }

  function draw(time) {
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
    ctx.fillStyle = P.bg;
    ctx.fillRect(0, 0, W, H);
    drawFloor(time);
    drawHalo();
    for (const e of EDGES) drawEdge(e);
    for (const p of packets) drawPacket(p);
    for (const n of NODES) drawNode(n, time);
    for (const n of NODES) drawLabel(n);
    if (hovered && hovered !== selected) drawReticle(hovered, time, 0.55);
    if (selected) drawReticle(selected, time, 1);
  }

  let last = performance.now();
  function frame(time) {
    step(time, time - last);
    last = time;
    draw(time);
    requestAnimationFrame(frame);
  }

  // ---------- panel and list ----------

  function indexLabel(n) {
    if (n.parent) return `↳ ${byId.get(n.parent).label}`;
    return `${pad(listed.indexOf(n))} / ${pad(digests.length)}`;
  }

  function el(tag, className, text) {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  }

  // Segments come from the exporter; only http(s) links become anchors.
  // Summary citations ([n]) become buttons when a handler is given; punctuation
  // right after a citation stays on its line.
  function inline(parent, segments, onRef) {
    let carry = "";
    for (const [i, segment] of segments.entries()) {
      const s = carry ? { ...segment, text: segment.text.slice(carry.length) } : segment;
      carry = "";
      if (s.ref && onRef) {
        const b = el("button", "ref", s.text);
        b.type = "button";
        b.addEventListener("click", () => onRef(s.ref));
        const next = segments[i + 1];
        const tail = next && !next.ref && !next.href && !next.bold && next.text.match(/^[.,;:!?)\]»”…]+/);
        if (tail) {
          const tie = el("span", "ref-tie");
          tie.append(b, tail[0]);
          parent.append(tie);
          carry = tail[0];
        } else {
          parent.append(b);
        }
      } else if (s.href && /^https?:\/\//i.test(s.href)) {
        const a = el("a", null, s.text);
        a.href = s.href;
        a.target = "_blank";
        a.rel = "noopener noreferrer";
        parent.append(a);
      } else if (s.bold) {
        parent.append(el("strong", null, s.text));
      } else {
        parent.append(document.createTextNode(s.text));
      }
    }
    return parent;
  }

  function fieldTone(label) {
    if (/^(sin confirmar|no confirmado|unconfirmed|unverified)/i.test(label)) return "warn";
    if (/^(siguiente paso|next step)/i.test(label)) return "next";
    return "";
  }

  function readingMinutes(edition) {
    const parts = [];
    const add = (segments) => segments.forEach((s) => parts.push(s.text));
    (edition.summary || []).forEach(add);
    for (const block of edition.blocks) {
      if (block.type === "section") parts.push(block.text);
      else if (block.type === "paragraph") add(block.text);
      else if (block.type === "list") block.items.forEach(add);
      else if (block.type === "item") {
        parts.push(block.title);
        for (const field of block.fields) {
          parts.push(field.label || "");
          add(field.value);
        }
      }
    }
    const words = parts.join(" ").split(/\s+/).filter(Boolean).length;
    return Math.max(1, Math.round(words / 220));
  }

  function renderEdition(n) {
    const edition = EDITIONS[n.id];
    if (!edition) return [el("p", "empty", tr(COPY.noEdition))];
    const out = [];
    const meta = el("p", "edition-meta");
    meta.append(
      el("span", "chip out", editionDate(edition.generatedAt, { dateStyle: "medium", timeStyle: "short" }) + " UTC"),
      el("span", "chip", edition.language.toUpperCase()),
      el("span", "chip", `${readingMinutes(edition)} ${tr(COPY.minutes)}`),
    );
    out.push(meta);
    if (edition.title) out.push(el("p", "edition-title", edition.title));
    const summary = edition.summary || [];
    if (!summary.length) {
      // Editions without a summary read as the full list of items.
      for (const block of edition.blocks) out.push(renderBlock(block));
      return out;
    }
    if (openStory) {
      const back = el("button", "story-back", `← ${tr(COPY.back)}`);
      back.type = "button";
      back.addEventListener("click", () => showStory(null));
      const section = edition.blocks.slice(0, edition.blocks.indexOf(openStory))
        .reverse().find((block) => block.type === "section");
      out.push(back);
      if (section) out.push(renderBlock(section));
      out.push(renderBlock(openStory));
      return out;
    }
    // Summary first; each citation and index entry opens its item.
    const openRef = (ref) => showStory(edition.blocks.find((block) => block.ref === ref));
    out.push(el("h3", "edition-section", tr(COPY.summary)));
    for (const paragraph of summary) out.push(inline(el("p", "edition-p edition-summary"), paragraph, openRef));
    for (const block of edition.blocks) {
      if (block.type !== "item") {
        out.push(renderBlock(block));
        continue;
      }
      const entry = el("button", "story-link");
      entry.type = "button";
      entry.dataset.block = String(edition.blocks.indexOf(block));
      if (block.ref) entry.append(el("span", "story-ref", `[${block.ref}]`));
      entry.append(el("span", "story-name", block.title), el("span", "story-go", "→"));
      entry.addEventListener("click", () => showStory(block));
      out.push(entry);
    }
    return out;
  }

  function renderBlock(block) {
    if (block.type === "section") return el("h3", "edition-section", block.text);
    if (block.type === "paragraph") return inline(el("p", "edition-p"), block.text);
    if (block.type === "list") {
      const ul = el("ul", "edition-list");
      for (const item of block.items) ul.append(inline(el("li"), item));
      return ul;
    }
    const story = el("article", "story");
    story.append(el("h4", null, block.ref ? `[${block.ref}] ${block.title}` : block.title));
    const rows = el("ul", "rows");
    for (const field of block.fields) {
      const li = el("li", field.label ? fieldTone(field.label) : "plain");
      if (field.label) li.append(el("b", null, field.label));
      li.append(inline(el("span"), field.value));
      rows.append(li);
    }
    story.append(rows);
    return story;
  }

  // Opening an item swaps the summary for its detail card; going back
  // returns focus to that item's entry in the index.
  function showStory(block) {
    if (!block && !openStory) return;
    const previous = openStory;
    openStory = block || null;
    renderDetails();
    if (openStory) {
      details.scrollTop = 0;
      detailsEdition.querySelector(".story-back")?.focus({ preventScroll: true });
    } else {
      const index = EDITIONS[selected.id].blocks.indexOf(previous);
      detailsEdition.querySelector(`.story-link[data-block="${index}"]`)?.focus();
    }
  }

  function renderDetails() {
    const n = selected;
    const reading = Boolean(n) && n.kind === "digest" && n.status === "live";
    details.hidden = !n;
    panel.classList.toggle("open", Boolean(n));
    panel.classList.toggle("reading", reading);
    if (!n) return;
    detailsIndex.textContent = indexLabel(n);
    detailsStatus.className = `status ${n.status}`;
    detailsStatus.textContent = tr(STATUS[n.kind === "source" ? "source" : n.status]);
    detailsTitle.textContent = tr(n.title);
    detailsSummary.textContent = tr(n.summary) || "";
    detailsSummary.hidden = !n.summary;
    detailsEdition.replaceChildren(...(reading ? renderEdition(n) : []));

    const rows = [];
    for (const [key, label] of FIELDS) {
      if (!n[key]) continue;
      const li = el("li");
      li.append(el("b", null, tr(label)), el("span", null, tr(n[key])));
      rows.push(li);
    }
    if (reading && rows.length) rows.unshift(el("li", "rows-head", tr(COPY.about)));
    detailsRows.replaceChildren(...rows);
    detailsRows.hidden = rows.length === 0;
  }

  const listButtons = new Map();

  function renderList() {
    for (const n of listed) {
      const b = document.createElement("button");
      b.type = "button";
      b.className = `rect ${n.status}`;
      if (n.kind === "digest") b.style.setProperty("--hue", `var(--hue-${n.id})`);
      const idx = document.createElement("span");
      idx.className = "idx";
      idx.textContent = pad(listed.indexOf(n));
      const name = document.createElement("span");
      name.className = "name";
      name.textContent = n.label;
      const glyph = document.createElement("span");
      glyph.className = "glyph";
      glyph.setAttribute("aria-hidden", "true");
      glyph.textContent = n.kind === "core" ? "◆" : n.status === "live" ? "●" : "○";
      b.append(idx, name);
      if (EDITIONS[n.id] && n.status === "live") b.append(el("span", "meta"));
      b.append(glyph);
      b.addEventListener("click", () => select(selected === n ? null : n));
      b.addEventListener("pointerenter", () => { hovered = n; });
      b.addEventListener("pointerleave", () => { if (hovered === n) hovered = null; });
      b.addEventListener("focus", () => { hovered = n; });
      b.addEventListener("blur", () => { if (hovered === n) hovered = null; });
      listButtons.set(n, b);
      list.append(b);
    }
    syncList();
  }

  function syncList() {
    const active = selected && selected.parent ? byId.get(selected.parent) : selected;
    for (const [n, b] of listButtons) {
      const meta = b.querySelector(".meta");
      const date = meta ? editionDate(EDITIONS[n.id].generatedAt, { day: "2-digit", month: "short" }).replace(".", "") : "";
      if (meta) meta.textContent = date;
      b.setAttribute("aria-pressed", String(n === active));
      b.setAttribute("aria-label", [n.label, tr(STATUS[n.status]), date].filter(Boolean).join(" · "));
    }
  }

  // Every watcher has a shareable address: #cybersecurity-digest opens its reader.
  function select(n, { updateHash = true } = {}) {
    if (n && n.kind === "edition") n = byId.get(n.parent);
    const changed = n !== selected;
    selected = n;
    if (changed) openStory = null;
    renderDetails();
    syncList();
    measure();
    if (changed) details.scrollTop = 0;
    if (updateHash) {
      try {
        history.replaceState(null, "", n ? `#${n.id}` : `${location.pathname}${location.search}`);
      } catch { /* some file:// contexts refuse history updates */ }
    }
  }

  function selectFromHash() {
    const n = byId.get(decodeURIComponent(location.hash.slice(1)));
    select(n || null, { updateHash: false });
  }

  // ---------- pointer ----------

  function hit(x, y) {
    let best = null, bd = Infinity;
    for (const n of NODES) {
      const d = Math.hypot(n.x - x, n.y - y);
      if (d < n.rr + 8 && d < bd) { best = n; bd = d; }
    }
    return best;
  }

  canvas.addEventListener("pointerdown", (e) => {
    const n = hit(e.clientX, e.clientY);
    drag = { node: n, dx: n ? n.x - e.clientX : 0, dy: n ? n.y - e.clientY : 0, sx: e.clientX, sy: e.clientY, moved: false };
    canvas.setPointerCapture(e.pointerId);
    if (n) canvas.classList.add("dragging");
  });

  canvas.addEventListener("pointermove", (e) => {
    if (!drag) {
      hovered = hit(e.clientX, e.clientY);
      canvas.classList.toggle("hovering", !!hovered);
      return;
    }
    if (Math.hypot(e.clientX - drag.sx, e.clientY - drag.sy) > 4) drag.moved = true;
    const n = drag.node;
    if (!n || !drag.moved) return;
    // homes stay fixed: on release the spring in step() pulls the node back
    n.x = clamp(e.clientX + drag.dx, region.x0 + n.rr, region.x1 - n.rr);
    n.y = clamp(e.clientY + drag.dy, region.y0 + n.rr, region.y1 - n.rr);
  });

  const endDrag = (e) => {
    if (!drag) return;
    if (!drag.moved && e.type === "pointerup") select(drag.node && drag.node !== selected ? drag.node : null);
    drag = null;
    canvas.classList.remove("dragging");
  };
  canvas.addEventListener("pointerup", endDrag);
  canvas.addEventListener("pointercancel", endDrag);
  canvas.addEventListener("pointerleave", () => { if (!drag) hovered = null; });

  // ---------- controls ----------

  function applyLang(l) {
    root.dataset.lang = l;
    root.lang = l;
    langToggle.textContent = l === "es" ? "EN" : "ES";
    themeToggle.setAttribute("aria-label", l === "es" ? "Cambiar tema" : "Toggle theme");
    canvas.setAttribute("aria-label", l === "es"
      ? "Mapa de The Watchers: cada watcher conectado a la red, con sus fuentes y su última edición."
      : "Map of The Watchers: every watcher linked to the network, with its sources and latest edition.");
    sysLast.textContent = latestEdition
      ? editionDate(latestEdition, { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" }) + " UTC"
      : "—";
    renderDetails();
    syncList();
  }

  function applyTheme(th) {
    root.dataset.theme = th;
    readPalette();
  }

  langToggle.addEventListener("click", () => {
    prefs.lang = lang() === "es" ? "en" : "es";
    applyLang(prefs.lang);
    savePrefs();
  });

  themeToggle.addEventListener("click", () => {
    prefs.theme = root.dataset.theme === "dark" ? "light" : "dark";
    applyTheme(prefs.theme);
    savePrefs();
  });

  document.addEventListener("keydown", (e) => {
    if (e.key !== "Escape") return;
    if (openStory) showStory(null);
    else if (selected) select(null);
  });
  document.getElementById("detailsClose").addEventListener("click", () => select(null));

  window.addEventListener("resize", resize);
  window.addEventListener("hashchange", selectFromHash);

  function tick() {
    const d = new Date();
    sysClock.textContent = [d.getHours(), d.getMinutes(), d.getSeconds()].map(pad).join(":");
  }

  // ---------- boot ----------

  applyTheme(prefs.theme === "light" ? "light" : "dark");
  renderList();
  applyLang(prefs.lang === "en" ? "en" : "es");
  resize();
  seed();
  selectFromHash();
  tick();
  setInterval(tick, 1000);
  requestAnimationFrame(frame);
})();
